// upstream-allowlist-data.gen.ts — GENERATED DATA (registry sweep 2026-10-13, codegen at HEAD).
// Every pinned value below was extracted from REAL component base-image layer bytes
// (anonymous registry pulls: Docker Hub library/node, library/postgres,
// tailscale/tailscale, nousresearch/hermes-agent; GHCR berriai/litellm — 7 unique
// tags x amd64+arm64), re-matched through the gate’s own patterns, and provenance-
// verified against the exact upstream release artifact (PyPI wheel / npm registry
// tarball / raw.githubusercontent at the pinned version or git tag). 149 entries;
// THREE fail-closed provenance planes (any one, exactly one used per entry):
//   fileSha256 / fileSha256s — byte-identity vs the upstream artifact
//   markers — required substrings verified in every real member file
//   markerFn — named shape predicate over the whole file (see MARKER_FNS)
// Secret-SHAPED matched values (AWS doc example AKIA keys, the evals probe slack
// token, PEM/DSA/RSA/EC self-test fixtures) are pinned as sha256(value) DIGESTS:
// the raw secret-shaped bytes never enter this repo, and a same-shape token with a
// different value still rejects (digest not in the closed set).

export interface UpstreamFileEntry {
  name: string;
  patterns: readonly string[];
  matchKind: "prefix" | "suffix" | "re";
  match: string;
  fileSha256: string | null;
  /** per-file SHA pins for multi-file entries — key: absolute normalized path */
  fileSha256s: Readonly<Record<string, string>> | null;
  markers: readonly string[] | null;
  markerFn: string | null;
  occurrences: ReadonlyArray<{ literal?: string; sha256?: string }>;
}

export const MARKER_FNS: Record<string, (text: string, matchIndex?: number) => boolean> = {
  fernClientShape: (text) => text.includes('auto-generated by Fern from our API Definition'),
  selfTestShape: (text) => text.includes('from Crypto') || text.includes('SelfTest'),
  npmReadmeShape: (text) =>
    text.includes('registry') && (text.includes('await ') || text.includes('```')) && (text.includes('token') || text.includes('npm')),
  ipAddressDocShape: (text) =>
    text.includes('IPv4') || text.includes('IPv6') || text.includes('Address4') || text.includes('Address6'),
  ipaddressStdlibShape: (text) =>
    text.includes('class IPv4Address(_BaseV4, _BaseAddress):') && text.includes('class IPv6Address(_BaseV6, _BaseAddress):') && text.includes('_private_networks = ['),
  kernelUapiShape: (text) =>
    text.includes('SPDX-License-Identifier') || text.includes('#ifndef'),
  perlCoreShape: (text) =>
    text.includes('package ') || text.includes('=head1 NAME'),
  dockerFishShape: (text) => text.includes('docker.fish - docker completions for fish shell'),
  awsShape: (text) =>
    text.includes('"version": "1.0"') || text.includes('Generate a signed URL for Amazon CloudFront'),
  tornadoKeyShape: (text) => text.includes('BEGIN PRIVATE KEY'),
  npmDocsShape: (text) => text.includes('npm token'),
};

